def sumDivisors(n: int) -> int:
    total = 0
    i = 1
    while i <= n:
        if n % i == 0:
            total += i
        i += 1
    return total

def main() -> None:
    test_cases = [1, 2, 6, 12, 28]
    for n in test_cases:
        result = sumDivisors(n)
        print(result)

if __name__ == "__main__":
    main()

