#include <stdio.h>
#include <stdbool.h>
#include <math.h>

long long sumDivisors(long long n) {
    long long sum = 0;
    for (long long i = 1; i <= n; i++) {
        if (n % i == 0) {
            sum += i;
        }
    }
    return sum;
}

int main() {
    long long test_cases[] = {1, 2, 12, 28, 100};
    int num_tests = sizeof(test_cases) / sizeof(test_cases[0]);

    for (int i = 0; i < num_tests; i++) {
        long long result = sumDivisors(test_cases[i]);
        printf("%lld\n", result);
    }

    return 0;
}

