import java.util.*;

public class Solution {
    public static long sumDivisors(long n) {
        long sum = 0;
        for (long i = 1; i <= n; i++) {
            if (n % i == 0) {
                sum += i;
            }
        }
        return sum;
    }

    public static void main(String[] args) {
        // Test case 1: n = 1 (smallest positive)
        System.out.println(sumDivisors(1));

        // Test case 2: n = 6 (perfect number, sum = 1+2+3+6 = 12)
        System.out.println(sumDivisors(6));

        // Test case 3: n = 12 (sum = 1+2+3+4+6+12 = 28)
        System.out.println(sumDivisors(12));

        // Test case 4: n = 17 (prime number, sum = 1+17 = 18)
        System.out.println(sumDivisors(17));

        // Test case 5: n = 100 (larger composite)
        System.out.println(sumDivisors(100));
    }
}
